func prefixFieldClashes(data Fields, reportCaller bool) {
	if t, ok := data["time"]; ok {
		data["fields.time"] = t
	}

	if m, ok := data["msg"]; ok {
		data["fields.msg"] = m
	}

	if l, ok := data["level"]; ok {
		data["fields.level"] = l
	}

	// If reportCaller is not set, 'func' will not conflict.
	if reportCaller {
		if l, ok := data["func"]; ok {
			data["fields.func"] = l
		}
	}
}
